<?php
require_once '../includes/auth.php';requireActiveUser();requireTenantContext();requireModulePermission('hotspot','create');global $conn;$tenantId=(int)getCurrentTenantId();$error='';$packages=[];
$q=$conn->prepare("SELECT id,name,duration_minutes,price FROM hotspot_packages WHERE tenant_id=? AND status='active' ORDER BY name");$q->bind_param('i',$tenantId);$q->execute();$z=$q->get_result();while($r=$z->fetch_assoc())$packages[]=$r;$q->close();
if($_SERVER['REQUEST_METHOD']==='POST'){requireCsrf();$packageId=(int)($_POST['package_id']??0);$qty=min(500,max(1,(int)($_POST['quantity']??1)));$expires=trim($_POST['expires_at']??'');$packageOk=false;foreach($packages as $p)if((int)$p['id']===$packageId)$packageOk=true;
if(!$packageOk)$error='Select a valid active hotspot plan.';else{for($i=0;$i<$qty;$i++){do{$code=strtoupper(substr(bin2hex(random_bytes(5)),0,10));$q=$conn->prepare("SELECT id FROM hotspot_access_codes WHERE tenant_id=? AND code=?");$q->bind_param('is',$tenantId,$code);$q->execute();$exists=$q->get_result()->num_rows>0;$q->close();}while($exists);$q=$conn->prepare("INSERT INTO hotspot_access_codes(tenant_id,code,package_id,status,expires_at) VALUES(?,?,?,'unused',NULLIF(?,''))");$q->bind_param('iiis',$tenantId,$code,$packageId,$expires);if(!$q->execute()){$error=$q->error?:'Unable to generate codes.';$q->close();break;}$q->close();}if($error==='')redirect('access_codes.php');}}
$pageTitle='Generate Access Codes';require_once '../includes/header.php';?><div class="dashboard-card"><h2>Generate Hotspot Access Codes</h2><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post"><?=csrfField()?><div class="form-group"><label>Hotspot Plan</label><select name="package_id" required><option value="">Select plan</option><?php foreach($packages as $p):?><option value="<?=e($p['id'])?>"><?=e($p['name'])?> — <?=e($p['duration_minutes'])?> min — KES <?=e($p['price'])?></option><?php endforeach;?></select></div><div class="form-group"><label>Quantity</label><input type="number" name="quantity" min="1" max="500" value="10" required></div><div class="form-group"><label>Expiry (optional)</label><input type="datetime-local" name="expires_at"></div><button type="submit">Generate Codes</button> <a href="access_codes.php">Cancel</a></form></div><?php require_once '../includes/footer.php';?>